import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> {'price', 'qty', 'side', 'active'}
    trades = []
    seq = 0

    def clean_buy():
        while buy_heap:
            _, _, oid = buy_heap[0]
            rec = book.get(oid)
            if rec is None or (not rec['active']) or rec['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            _, _, oid = sell_heap[0]
            rec = book.get(oid)
            if rec is None or (not rec['active']) or rec['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                key, s, sid = sell_heap[0]
                sprice = book[sid]['price']
                if price is not None and sprice > price:
                    break
                trade_qty = min(remaining, book[sid]['qty'])
                trades.append([oid, sid, sprice, trade_qty])
                remaining -= trade_qty
                book[sid]['qty'] -= trade_qty
                if book[sid]['qty'] == 0:
                    book[sid]['active'] = False
                    heapq.heappop(sell_heap)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'price': price, 'qty': remaining, 'side': 'buy', 'active': True}
                heapq.heappush(buy_heap, (-price, seq, oid))
                seq += 1

        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                key, s, bid = buy_heap[0]
                bprice = book[bid]['price']
                if price is not None and bprice < price:
                    break
                trade_qty = min(remaining, book[bid]['qty'])
                trades.append([bid, oid, bprice, trade_qty])
                remaining -= trade_qty
                book[bid]['qty'] -= trade_qty
                if book[bid]['qty'] == 0:
                    book[bid]['active'] = False
                    heapq.heappop(buy_heap)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'price': price, 'qty': remaining, 'side': 'sell', 'active': True}
                heapq.heappush(sell_heap, (price, seq, oid))
                seq += 1

    return trades

